#include "ann.h"
#include <string.h>
static uint64_t get(const uint8_t *p,unsigned n){uint64_t x=0;unsigned i;for(i=0;i<n;i++)x|=(uint64_t)p[i]<<(8*i);return x;}
static void put(uint8_t*p,uint64_t x,unsigned n){unsigned i;for(i=0;i<n;i++)p[i]=(uint8_t)(x>>(8*i));}
static uint32_t crc(const uint8_t*p,size_t n){uint32_t c=~0u;size_t i;unsigned b;for(i=0;i<n;i++){c^=(i>=108&&i<112)?0:p[i];for(b=0;b<8;b++)c=(c>>1)^(0xedb88320u& (0u-(c&1)));}return ~c;}
int ann_encode(const ann_packet*p,uint8_t*b,size_t cap){unsigned i;size_t z=ANN_HEADER+p->payload_len;if(cap<z||z>250||p->path_len>8||p->type<1||p->type>7)return -1;memset(b,0,z);b[0]=0x41;b[1]=0x4e;b[2]=1;b[3]=p->type;b[4]=p->flags;b[5]=p->ttl;b[6]=p->path_len;b[7]=p->index;put(b+8,p->origin,8);put(b+16,p->dst,8);put(b+24,p->boot,4);put(b+28,p->seq,4);put(b+32,p->remaining_ms,4);put(b+36,p->key,4);put(b+40,p->payload_len,2);b[42]=p->kind;for(i=0;i<8;i++)put(b+44+8*i,p->path[i],8);memcpy(b+112,p->payload,p->payload_len);put(b+108,crc(b,z),4);return (int)z;}
int ann_decode(ann_packet*p,const uint8_t*b,size_t z){unsigned i;if(z<112||z>250||b[0]!=0x41||b[1]!=0x4e||b[2]!=1||b[3]<1||b[3]>7||b[43]||b[6]>8||get(b+40,2)!=z-112||get(b+108,4)!=crc(b,z))return -1;memset(p,0,sizeof(*p));p->type=b[3];p->flags=b[4];p->ttl=b[5];p->path_len=b[6];p->index=b[7];p->origin=get(b+8,8);p->dst=get(b+16,8);p->boot=(uint32_t)get(b+24,4);p->seq=(uint32_t)get(b+28,4);p->remaining_ms=(uint32_t)get(b+32,4);p->key=(uint32_t)get(b+36,4);p->payload_len=(uint16_t)get(b+40,2);p->kind=b[42];for(i=0;i<8;i++)p->path[i]=get(b+44+8*i,8);memcpy(p->payload,b+112,p->payload_len);if(!p->origin||p->origin>>48||p->dst>>48||!p->boot||!p->remaining_ms||p->remaining_ms>60000||p->ttl>8||p->flags>1)return -1;for(i=0;i<p->path_len;i++)if(!p->path[i]||p->path[i]>>48)return -1;if(p->type!=ANN_HELLO&&(!p->dst||!p->path_len||p->index>=p->path_len||p->path[0]!=p->origin))return -1;if((p->type==ANN_DATA||p->type==ANN_CANCEL||p->type==ANN_ACK||p->type==ANN_RREP||p->type==ANN_ERROR)&&p->path[p->path_len-1]!=p->dst)return -1;if(p->type==ANN_DATA&&(p->kind<1||p->kind>3))return -1;return 0;}
static void event(ann_node*n,unsigned type,const ann_packet*p,int status){ann_event e;unsigned pos;memset(&e,0,sizeof(e));e.type=(uint8_t)type;e.origin=p?p->origin:n->id;e.boot=p?p->boot:n->boot;e.seq=p?p->seq:0;e.t_ms=n->now;e.status=status;if(p){e.payload_bytes=p->payload_len;e.frame_bytes=112+p->payload_len;}if(n->event_count==ANN_QUEUE){n->event_overflow++;return;}pos=(n->event_head+n->event_count++)%ANN_QUEUE;n->events[pos]=e;}
static int queue(ann_node*n,ann_id next,const ann_packet*p){unsigned k;if(!n->active)return -1;if(n->out_count==ANN_QUEUE){n->queue_overflow++;return -1;}k=(n->out_head+n->out_count++)%ANN_QUEUE;n->out[k].next=next;n->out[k].packet=*p;n->out[k].queued_ms=n->now;return 0;}
static ann_route *route(ann_node*n,ann_id dst){unsigned i;for(i=0;i<16;i++)if(n->routes[i].used&&n->routes[i].until>n->now&&n->routes[i].dst==dst)return &n->routes[i];return NULL;}
static void save_route(ann_node*n,const ann_packet*p){unsigned i;ann_route*r=route(n,p->dst);if(!r){for(i=0;i<16;i++)if(!n->routes[i].used||n->routes[i].until<=n->now){r=&n->routes[i];break;}}if(!r){n->rejected++;return;}r->used=1;r->dst=p->dst;r->len=p->path_len;memcpy(r->path,p->path,sizeof(r->path));r->until=n->now+10000;}
static ann_seen *seen(ann_node*n,const ann_packet*p,int add){unsigned i;ann_seen*empty=NULL;for(i=0;i<16;i++){ann_seen*s=&n->seen[i];if(s->used&&s->until>n->now&&s->origin==p->origin&&s->boot==p->boot&&s->seq==p->seq&&s->type==p->type)return s;if(!s->used||s->until<=n->now)empty=s;}if(!add||!empty)return NULL;*empty=(ann_seen){1,0,p->origin,p->boot,p->seq,p->type,n->now+400,0,0};return empty;}
/* One 64-sequence DATA window per origin/boot, not one permanent slot per packet.
 * Never evict a live stream; out-of-window old DATA is rejected without ACK. */
static ann_seen *data_seen(ann_node*n,const ann_packet*p,int *known,int *cancelled){unsigned i;ann_seen*s=NULL,*empty=NULL;uint32_t delta;*known=*cancelled=0;for(i=0;i<16;i++){ann_seen*v=n->seen+i;if(v->used&&v->until>n->now&&v->type==ANN_DATA&&v->origin==p->origin&&v->boot==p->boot){s=v;break;}if(!v->used||v->until<=n->now)empty=v;}if(!s){if(!empty)return NULL;s=empty;*s=(ann_seen){1,0,p->origin,p->boot,p->seq,ANN_DATA,n->now+63000,0,0};}if(p->seq>s->seq){delta=p->seq-s->seq;s->bitmap=delta>=64?0:s->bitmap<<delta;s->cancel_bitmap=delta>=64?0:s->cancel_bitmap<<delta;s->seq=p->seq;}delta=s->seq-p->seq;if(delta>=64){*known=2;return s;}*known=(s->bitmap&(UINT64_C(1)<<delta))!=0;*cancelled=(s->cancel_bitmap&(UINT64_C(1)<<delta))!=0;s->until=n->now+63000;return s;}
static ann_pending *pending(ann_node*n,uint32_t boot,uint32_t seq){unsigned i;for(i=0;i<8;i++)if(n->pending[i].used&&n->pending[i].packet.boot==boot&&n->pending[i].packet.seq==seq)return &n->pending[i];return NULL;}
static void attempt(ann_node*n,ann_pending*t){ann_packet p=t->packet;ann_route*r=route(n,p.dst);p.remaining_ms=(uint32_t)(t->deadline-n->now);p.ttl=8;if(r){if(t->attempts>=3){t->used=0;event(n,ANN_EXPIRED,&p,3);return;}p.path_len=r->len;memcpy(p.path,r->path,sizeof(p.path));p.index=1;t->attempts++;queue(n,p.path[1],&p);}else{if(t->discoveries>=3){t->used=0;event(n,ANN_EXPIRED,&p,2);return;}p.type=ANN_RREQ;p.payload_len=0;p.path_len=1;p.path[0]=n->id;p.index=0;t->discoveries++;queue(n,0,&p);}t->due=n->now+500;}
void ann_init(ann_node*n,ann_id id,uint32_t boot){memset(n,0,sizeof(*n));n->id=id;n->boot=boot;}
void ann_start(ann_node*n,uint64_t now){ann_packet p;if(n->active||!n->id||n->id>>48||!n->boot)return;n->now=now;n->active=1;memset(&p,0,sizeof(p));p.type=ANN_HELLO;p.origin=n->id;p.boot=n->boot;p.remaining_ms=5000;p.ttl=1;queue(n,0,&p);}
void ann_stop(ann_node*n,uint64_t now){unsigned i;n->now=now;for(i=0;i<8;i++)if(n->pending[i].used){event(n,ANN_CANCELLED,&n->pending[i].packet,1);n->pending[i].used=0;}n->active=0;n->out_count=0;}
int ann_submit(ann_node*n,ann_id dst,uint8_t kind,uint32_t key,const void*data,size_t len,uint32_t life,uint8_t flags,uint64_t now,uint32_t*seq){unsigned i;ann_pending*t=NULL;if(now<n->now||!n->active||!dst||dst==n->id||dst>>48||!life||life>60000||len>138||(!data&&len)||kind<1||kind>3||flags>1||n->seq==UINT32_MAX||n->out_count>=32)return -1;n->now=now;for(i=0;i<8;i++)if(!n->pending[i].used){t=&n->pending[i];break;}if(!t){n->rejected++;return -2;}memset(t,0,sizeof(*t));t->used=1;t->packet.type=ANN_DATA;t->packet.origin=n->id;t->packet.dst=dst;t->packet.boot=n->boot;t->packet.seq=++n->seq;t->packet.kind=kind;t->packet.key=key;t->packet.flags=flags;t->packet.payload_len=(uint16_t)len;if(len)memcpy(t->packet.payload,data,len);t->deadline=now+life;if(seq)*seq=n->seq;event(n,ANN_GENERATED,&t->packet,0);attempt(n,t);return 0;}
void ann_tick(ann_node*n,uint64_t now){unsigned i;if(now<n->now)return;n->now=now;for(i=0;i<16;i++)if(n->states[i].used&&n->states[i].until<=now)n->states[i].used=0;if(!n->active)return;for(i=0;i<8;i++){ann_pending*t=&n->pending[i];if(!t->used)continue;if(now>=t->deadline){event(n,ANN_EXPIRED,&t->packet,1);t->used=0;}else if(now>=t->due)attempt(n,t);}}
int ann_next_tx(ann_node*n,ann_out*out,uint64_t now){while(n->active&&n->out_count){uint64_t age;*out=n->out[n->out_head];n->out_head=(n->out_head+1)%32;n->out_count--;age=now>=out->queued_ms?now-out->queued_ms:UINT64_MAX;if(age>=out->packet.remaining_ms)continue;out->packet.remaining_ms-=(uint32_t)age;return 1;}return 0;}
int ann_next_event(ann_node*n,ann_event*e){if(!n->event_count)return 0;*e=n->events[n->event_head];n->event_head=(n->event_head+1)%32;n->event_count--;return 1;}
static int reverse(ann_node*n,ann_packet*p,unsigned type){p->type=(uint8_t)type;p->payload_len=0;p->index=(uint8_t)(p->path_len-1);if(!p->index)return -1;p->index--;p->ttl=8;return queue(n,p->path[p->index],p);}
static int state_accept(ann_node*n,const ann_packet*p){unsigned i;ann_state*s=NULL;for(i=0;i<16;i++){ann_state*v=&n->states[i];if(v->used&&v->until>n->now&&v->origin==p->origin&&v->boot==p->boot&&v->key==p->key){if(p->seq<=v->seq)return 0;s=v;break;}}if(!s)for(i=0;i<16;i++)if(!n->states[i].used||n->states[i].until<=n->now){s=&n->states[i];break;}if(!s)return -1;s->used=1;s->origin=p->origin;s->boot=p->boot;s->key=p->key;s->seq=p->seq;s->len=p->payload_len;s->until=n->now+p->remaining_ms;memcpy(s->data,p->payload,p->payload_len);return 1;}
int ann_receive(ann_node*n,ann_id from,const uint8_t*b,size_t len,uint64_t now){ann_packet p;unsigned i;ann_seen*s;ann_pending*t;int known,cancelled;if(!n->active||now<n->now||ann_decode(&p,b,len)||!from||from==n->id)return -1;n->now=now;event(n,ANN_RX,&p,0);
 if(p.type==ANN_HELLO){ann_peer*v=NULL;if(p.origin!=from)return -1;for(i=0;i<16;i++)if(n->peers[i].used&&n->peers[i].id==from){v=&n->peers[i];break;}if(!v)for(i=0;i<16;i++)if(!n->peers[i].used||n->peers[i].until<=now){v=&n->peers[i];break;}if(v)*v=(ann_peer){1,from,p.boot,now+5000};return 0;}
 if(p.type==ANN_RREQ){if(p.path[p.path_len-1]!=from)return -1;for(i=0;i<p.path_len;i++)if(p.path[i]==n->id)return -1;if(seen(n,&p,0))return 0;if(!seen(n,&p,1)||p.path_len==8||!p.ttl)return -1;p.path[p.path_len++]=n->id;p.ttl--;if(p.dst==n->id)return reverse(n,&p,ANN_RREP);p.index=p.path_len-1;return queue(n,0,&p);}
 if(p.path[p.index]!=n->id)return -1;
 if(p.type==ANN_RREP||p.type==ANN_ACK||p.type==ANN_ERROR){if(p.index+1>=p.path_len||p.path[p.index+1]!=from)return -1;if(p.index){if(!p.ttl)return -1;p.index--;p.ttl--;return queue(n,p.path[p.index],&p);}if(p.origin!=n->id)return -1;t=pending(n,p.boot,p.seq);if(!t)return 0;if(p.type==ANN_RREP){save_route(n,&p);attempt(n,t);}else if(p.type==ANN_ACK){n->confirmed++;event(n,ANN_CONFIRMED,&p,0);t->used=0;}else{ann_route*r=route(n,p.dst);if(r)r->used=0;t->due=now+500;}return 0;}
 if(!p.index||p.path[p.index-1]!=from)return -1;
 if(p.dst!=n->id){if(!p.ttl||p.index+1>=p.path_len)return -1;p.index++;p.ttl--;return queue(n,p.path[p.index],&p);}
 if(p.type==ANN_CANCEL){uint64_t bit;p.type=ANN_DATA;s=data_seen(n,&p,&known,&cancelled);if(!s)return -1;if(known==2)return 0;bit=UINT64_C(1)<<(s->seq-p.seq);if(!known){s->bitmap|=bit;s->cancel_bitmap|=bit;}event(n,ANN_CANCELLED,&p,known&&!cancelled?1:0);return 0;}
 if(p.type!=ANN_DATA)return -1;
 s=data_seen(n,&p,&known,&cancelled);if(!s){n->rejected++;event(n,ANN_REJECTED,&p,2);return -1;}
 if(known){n->duplicates++;event(n,ANN_DUPLICATE,&p,known==2?3:cancelled);if(known==1&&!cancelled)return reverse(n,&p,ANN_ACK);return 0;}
 if(p.kind==ANN_STATE){int r=state_accept(n,&p);if(r<0){n->rejected++;return -1;}if(!r){s->bitmap|=UINT64_C(1)<<(s->seq-p.seq);event(n,ANN_DUPLICATE,&p,2);return reverse(n,&p,ANN_ACK);}}
 s->bitmap|=UINT64_C(1)<<(s->seq-p.seq);
 n->delivered++;event(n,p.kind==ANN_ECHO?ANN_ECHOED:ANN_DELIVERED,&p,0);
 if(p.flags&1){uint8_t echo[138];uint32_t seq;size_t z=p.payload_len;memcpy(echo,p.payload,z);if(z>=8){put(echo,p.boot,4);put(echo+4,p.seq,4);ann_submit(n,p.origin,ANN_ECHO,0,echo,z,p.remaining_ms,0,now,&seq);}}
 return reverse(n,&p,ANN_ACK);
}
void ann_tx_result(ann_node*n,const ann_out*out,int ok,uint64_t now){ann_packet p=out->packet;ann_route*r;ann_pending*t;if(now<n->now)return;n->now=now;if(ok||p.type!=ANN_DATA)return;if(p.index==1){r=route(n,p.dst);if(r)r->used=0;t=pending(n,p.boot,p.seq);if(t)t->due=now+500;}else if(p.index>1){p.type=ANN_ERROR;p.payload_len=0;p.index-=2;p.ttl=8;queue(n,p.path[p.index],&p);}}
int ann_cancel(ann_node*n,uint32_t seq,uint64_t now){ann_pending*t;ann_route*r;ann_packet p;if(now<n->now)return -1;n->now=now;t=pending(n,n->boot,seq);if(!t)return -1;p=t->packet;r=route(n,p.dst);if(r){p.type=ANN_CANCEL;p.payload_len=0;p.path_len=r->len;memcpy(p.path,r->path,sizeof(p.path));p.index=1;p.ttl=8;p.remaining_ms=(uint32_t)(t->deadline>now?t->deadline-now:1);queue(n,p.path[1],&p);}t->used=0;event(n,ANN_CANCELLED,&p,0);return 0;}
